import java.io.*;
import java.util.*;

public class B {
    enum Zone { OUTSIDE, INSIDE }

    static class Counter {
        Zone zone = Zone.OUTSIDE;
        boolean wordStart = true;
        int curOut = 0;
        int maxOut = 0;
        int insideWords = 0;

        void add(char c) {
            if (c == '(') {
                zone = Zone.INSIDE;
                wordStart = true;
                curOut = 0;
            } else if (c == ')') {
                zone = Zone.OUTSIDE;
                curOut = 0;
            } else if (zone == Zone.OUTSIDE) {
                if (c == '_') {
                    curOut = 0;
                } else {
                    curOut++;
                    if (curOut > maxOut) {
                        maxOut = curOut;
                    }
                }
            } else {
                if (c == '_') {
                    wordStart = true;
                } else if (wordStart) {
                    insideWords++;
                    wordStart = false;
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        while (in.hasNext()) {
            int n = in.nextInt();
            String s = in.next();
            Counter counter = new Counter();
            for (int i = 0; i < n; i++) {
                counter.add(s.charAt(i));
            }
            out.println(counter.maxOut + " " + counter.insideWords);
        }
        out.flush();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }
        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
